-- Roles and skills cell (roles-skills), generated by solo-cell-kit from cell.yaml.
-- Every row belongs to a workspace and is visible only while the transaction
-- is bound to it (app.workspace_id). Do not edit once applied; add a new migration.

CREATE SCHEMA roles_skills;

CREATE FUNCTION roles_skills.current_workspace() RETURNS uuid
LANGUAGE sql STABLE AS $$
    SELECT nullif(current_setting('app.workspace_id', true), '')::uuid
$$;

CREATE TABLE roles_skills.personal_roles (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    slug                     text NOT NULL CHECK (length(slug) <= 200 AND length(slug) >= 1),
    name                     text NOT NULL CHECK (length(name) <= 500 AND length(name) >= 1),
    category                 text NOT NULL CHECK (length(category) <= 200 AND length(category) >= 1),
    description              text,
    source_path              text,
    source                   text NOT NULL DEFAULT 'manual' CHECK (length(source) <= 200),
    status                   text NOT NULL DEFAULT 'active' CHECK (status IN ('planned', 'active', 'paused', 'retired')),
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id),
    UNIQUE (workspace_id, slug)
);
CREATE UNIQUE INDEX personal_roles_legacy ON roles_skills.personal_roles (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX personal_roles_category ON roles_skills.personal_roles (workspace_id, category);
CREATE INDEX personal_roles_status ON roles_skills.personal_roles (workspace_id, status);

CREATE TABLE roles_skills.role_goal_links (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    role_id                  text NOT NULL CHECK (length(role_id) <= 200 AND length(role_id) >= 1),
    goal_id                  bigint NOT NULL,
    link_type                text NOT NULL DEFAULT 'primary' CHECK (link_type IN ('primary', 'supporting')),
    source                   text NOT NULL DEFAULT 'manual' CHECK (length(source) <= 200),
    priority                 integer NOT NULL DEFAULT 3,
    allocation_percent       integer NOT NULL DEFAULT 0,
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id),
    UNIQUE (workspace_id, role_id, goal_id)
);
CREATE UNIQUE INDEX role_goal_links_legacy ON roles_skills.role_goal_links (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX role_goal_links_goal_id ON roles_skills.role_goal_links (workspace_id, goal_id);
CREATE INDEX role_goal_links_link_type ON roles_skills.role_goal_links (workspace_id, link_type);
CREATE INDEX role_goal_links_role_id ON roles_skills.role_goal_links (workspace_id, role_id);

CREATE TABLE roles_skills.skill_categories (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    name                     text NOT NULL CHECK (length(name) <= 200 AND length(name) >= 1),
    slug                     text NOT NULL CHECK (length(slug) <= 200 AND length(slug) >= 1),
    description              text,
    icon                     text CHECK (icon IS NULL OR (length(icon) <= 100)),
    color                    text CHECK (color IS NULL OR (length(color) <= 40)),
    parent_id                bigint,
    sort_order               integer NOT NULL DEFAULT 0,
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id),
    UNIQUE (workspace_id, name),
    UNIQUE (workspace_id, slug),
    FOREIGN KEY (workspace_id, parent_id) REFERENCES roles_skills.skill_categories (workspace_id, id)
);
CREATE UNIQUE INDEX skill_categories_legacy ON roles_skills.skill_categories (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX skill_categories_parent_id ON roles_skills.skill_categories (workspace_id, parent_id);

CREATE TABLE roles_skills.role_project_allocations (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    role_id                  text NOT NULL CHECK (length(role_id) <= 200 AND length(role_id) >= 1),
    project_id               bigint NOT NULL,
    goal_id                  bigint,
    allocation_percent       integer NOT NULL DEFAULT 0 CHECK (allocation_percent >= 0 AND allocation_percent <= 100),
    priority                 integer NOT NULL DEFAULT 3 CHECK (priority >= 1 AND priority <= 5),
    status                   text NOT NULL DEFAULT 'planned' CHECK (status IN ('planned', 'active', 'paused', 'completed')),
    source                   text NOT NULL DEFAULT 'manual' CHECK (length(source) <= 200),
    start_date               date,
    end_date                 date,
    notes                    text,
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id),
    UNIQUE (workspace_id, role_id, project_id, goal_id)
);
CREATE UNIQUE INDEX role_project_allocations_legacy ON roles_skills.role_project_allocations (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX role_project_allocations_goal_id ON roles_skills.role_project_allocations (workspace_id, goal_id);
CREATE INDEX role_project_allocations_project_id ON roles_skills.role_project_allocations (workspace_id, project_id);
CREATE INDEX role_project_allocations_role_id ON roles_skills.role_project_allocations (workspace_id, role_id);
CREATE INDEX role_project_allocations_status ON roles_skills.role_project_allocations (workspace_id, status);

CREATE TABLE roles_skills.personal_role_context_links (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    personal_role_id         bigint NOT NULL,
    context_id               bigint NOT NULL,
    relation_type            text NOT NULL DEFAULT 'belongs_to' CHECK (relation_type IN ('belongs_to', 'supports')),
    source                   text NOT NULL DEFAULT 'manual' CHECK (length(source) <= 200),
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id),
    UNIQUE (workspace_id, personal_role_id, context_id),
    FOREIGN KEY (workspace_id, personal_role_id) REFERENCES roles_skills.personal_roles (workspace_id, id)
);
CREATE UNIQUE INDEX personal_role_context_links_legacy ON roles_skills.personal_role_context_links (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX personal_role_context_links_context_id ON roles_skills.personal_role_context_links (workspace_id, context_id);
CREATE INDEX personal_role_context_links_personal_role_id ON roles_skills.personal_role_context_links (workspace_id, personal_role_id);
CREATE INDEX personal_role_context_links_relation_type ON roles_skills.personal_role_context_links (workspace_id, relation_type);

CREATE TABLE roles_skills.personal_role_goal_links (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    personal_role_id         bigint NOT NULL,
    goal_id                  bigint NOT NULL,
    link_type                text NOT NULL DEFAULT 'primary' CHECK (link_type IN ('primary', 'supporting')),
    source                   text NOT NULL DEFAULT 'manual' CHECK (length(source) <= 200),
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id),
    UNIQUE (workspace_id, personal_role_id, goal_id),
    FOREIGN KEY (workspace_id, personal_role_id) REFERENCES roles_skills.personal_roles (workspace_id, id)
);
CREATE UNIQUE INDEX personal_role_goal_links_legacy ON roles_skills.personal_role_goal_links (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX personal_role_goal_links_goal_id ON roles_skills.personal_role_goal_links (workspace_id, goal_id);
CREATE INDEX personal_role_goal_links_link_type ON roles_skills.personal_role_goal_links (workspace_id, link_type);
CREATE INDEX personal_role_goal_links_personal_role_id ON roles_skills.personal_role_goal_links (workspace_id, personal_role_id);

CREATE TABLE roles_skills.personal_role_project_links (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    personal_role_id         bigint NOT NULL,
    project_id               bigint NOT NULL,
    link_type                text NOT NULL DEFAULT 'primary' CHECK (link_type IN ('primary', 'supporting')),
    source                   text NOT NULL DEFAULT 'manual' CHECK (length(source) <= 200),
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id),
    UNIQUE (workspace_id, personal_role_id, project_id),
    FOREIGN KEY (workspace_id, personal_role_id) REFERENCES roles_skills.personal_roles (workspace_id, id)
);
CREATE UNIQUE INDEX personal_role_project_links_legacy ON roles_skills.personal_role_project_links (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX personal_role_project_links_link_type ON roles_skills.personal_role_project_links (workspace_id, link_type);
CREATE INDEX personal_role_project_links_personal_role_id ON roles_skills.personal_role_project_links (workspace_id, personal_role_id);
CREATE INDEX personal_role_project_links_project_id ON roles_skills.personal_role_project_links (workspace_id, project_id);

CREATE TABLE roles_skills.personal_role_task_links (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    personal_role_id         bigint NOT NULL,
    task_id                  bigint NOT NULL,
    link_type                text NOT NULL DEFAULT 'primary' CHECK (link_type IN ('primary', 'supporting')),
    source                   text NOT NULL DEFAULT 'manual' CHECK (length(source) <= 200),
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id),
    UNIQUE (workspace_id, personal_role_id, task_id),
    FOREIGN KEY (workspace_id, personal_role_id) REFERENCES roles_skills.personal_roles (workspace_id, id)
);
CREATE UNIQUE INDEX personal_role_task_links_legacy ON roles_skills.personal_role_task_links (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX personal_role_task_links_link_type ON roles_skills.personal_role_task_links (workspace_id, link_type);
CREATE INDEX personal_role_task_links_personal_role_id ON roles_skills.personal_role_task_links (workspace_id, personal_role_id);
CREATE INDEX personal_role_task_links_task_id ON roles_skills.personal_role_task_links (workspace_id, task_id);

CREATE TABLE roles_skills.skills (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    name                     text NOT NULL CHECK (length(name) <= 500 AND length(name) >= 1),
    slug                     text NOT NULL CHECK (length(slug) <= 200 AND length(slug) >= 1),
    description              text,
    category_id              bigint,
    level                    text CHECK (level IS NULL OR (level IN ('L1_deep', 'L2_capable', 'L3_overview', 'L4_outsource'))),
    target_level             text CHECK (target_level IS NULL OR (target_level IN ('L1_deep', 'L2_capable', 'L3_overview', 'L4_outsource'))),
    status                   text NOT NULL DEFAULT 'not_started' CHECK (status IN ('not_started', 'learning', 'practicing', 'proficient', 'expert')),
    priority                 integer NOT NULL DEFAULT 3,
    progress_percent         integer NOT NULL DEFAULT 0 CHECK (progress_percent >= 0 AND progress_percent <= 100),
    hours_invested           double precision NOT NULL DEFAULT 0,
    started_at               date,
    target_completion_date   date,
    key_concepts             text,
    resources                text,
    notes                    text,
    revenue_relevant         boolean NOT NULL DEFAULT false,
    last_practiced           date,
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id),
    UNIQUE (workspace_id, slug),
    FOREIGN KEY (workspace_id, category_id) REFERENCES roles_skills.skill_categories (workspace_id, id)
);
CREATE UNIQUE INDEX skills_legacy ON roles_skills.skills (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX skills_category_id ON roles_skills.skills (workspace_id, category_id);
CREATE INDEX skills_level ON roles_skills.skills (workspace_id, level);
CREATE INDEX skills_priority ON roles_skills.skills (workspace_id, priority);
CREATE INDEX skills_revenue_relevant ON roles_skills.skills (workspace_id, revenue_relevant);
CREATE INDEX skills_status ON roles_skills.skills (workspace_id, status);
CREATE INDEX skills_target_level ON roles_skills.skills (workspace_id, target_level);

CREATE TABLE roles_skills.role_path_steps (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    role_id                  text NOT NULL CHECK (length(role_id) <= 200 AND length(role_id) >= 1),
    step_key                 text NOT NULL CHECK (length(step_key) <= 200 AND length(step_key) >= 1),
    phase_id                 text NOT NULL CHECK (phase_id IN ('orient', 'learn', 'practice', 'evidence', 'operate')),
    title                    text NOT NULL CHECK (length(title) <= 500 AND length(title) >= 1),
    action                   text NOT NULL CHECK (length(action) >= 1),
    completion_rule          text NOT NULL CHECK (length(completion_rule) >= 1),
    skill_id                 bigint,
    target_progress          integer CHECK (target_progress IS NULL OR (target_progress >= 0 AND target_progress <= 100)),
    evidence_path            text,
    source_registry          text NOT NULL DEFAULT 'docs/ROLE-PATHS.yaml' CHECK (length(source_registry) <= 300),
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id),
    UNIQUE (workspace_id, role_id, step_key, source_registry),
    FOREIGN KEY (workspace_id, skill_id) REFERENCES roles_skills.skills (workspace_id, id)
);
CREATE UNIQUE INDEX role_path_steps_legacy ON roles_skills.role_path_steps (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX role_path_steps_phase_id ON roles_skills.role_path_steps (workspace_id, phase_id);
CREATE INDEX role_path_steps_role_id ON roles_skills.role_path_steps (workspace_id, role_id);
CREATE INDEX role_path_steps_skill_id ON roles_skills.role_path_steps (workspace_id, skill_id);
CREATE INDEX role_path_steps_source_registry ON roles_skills.role_path_steps (workspace_id, source_registry);

CREATE TABLE roles_skills.role_skill_links (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    role_id                  text NOT NULL CHECK (length(role_id) <= 200 AND length(role_id) >= 1),
    skill_id                 bigint NOT NULL,
    learning_path            text NOT NULL CHECK (length(learning_path) >= 1),
    link_type                text NOT NULL DEFAULT 'core' CHECK (link_type IN ('core', 'supporting')),
    source_registry          text NOT NULL DEFAULT 'docs/ROLE-LEARNING.yaml' CHECK (length(source_registry) <= 300),
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id),
    UNIQUE (workspace_id, role_id, skill_id),
    FOREIGN KEY (workspace_id, skill_id) REFERENCES roles_skills.skills (workspace_id, id)
);
CREATE UNIQUE INDEX role_skill_links_legacy ON roles_skills.role_skill_links (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX role_skill_links_link_type ON roles_skills.role_skill_links (workspace_id, link_type);
CREATE INDEX role_skill_links_role_id ON roles_skills.role_skill_links (workspace_id, role_id);
CREATE INDEX role_skill_links_skill_id ON roles_skills.role_skill_links (workspace_id, skill_id);

-- Idempotent creates: a key reserves the record id before the platform execution starts.
CREATE TABLE roles_skills.create_keys (
    workspace_id uuid NOT NULL,
    actor        uuid NOT NULL,
    kind         text NOT NULL CHECK (kind IN ('personal-role', 'personal-role-context-link', 'personal-role-goal-link', 'personal-role-project-link', 'personal-role-task-link', 'role-goal-link', 'skill-category', 'skill', 'role-path-step', 'role-project-allocation', 'role-skill-link')),
    key          text NOT NULL CHECK (length(key) BETWEEN 8 AND 200),
    record_id    bigint NOT NULL,
    created_at   timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, actor, kind, key)
);

-- Graph events, written in the same transaction as the change (at-least-once delivery).
CREATE TABLE roles_skills.outbox (
    id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    workspace_id    uuid NOT NULL,
    type            text NOT NULL,
    subject         text NOT NULL,
    execution_id    uuid,
    classification  text NOT NULL DEFAULT 'confidential',
    payload         jsonb NOT NULL,
    occurred_at     timestamptz NOT NULL DEFAULT now(),
    published_at    timestamptz,
    attempts        integer NOT NULL DEFAULT 0,
    next_attempt_at timestamptz NOT NULL DEFAULT now(),
    last_error      text,
    correlation_id  text
);
CREATE INDEX outbox_pending ON roles_skills.outbox (next_attempt_at) WHERE published_at IS NULL;

DO $$
DECLARE
    t text;
BEGIN
    FOREACH t IN ARRAY ARRAY['personal_roles', 'role_goal_links', 'skill_categories', 'role_project_allocations', 'personal_role_context_links', 'personal_role_goal_links', 'personal_role_project_links', 'personal_role_task_links', 'skills', 'role_path_steps', 'role_skill_links', 'create_keys', 'outbox'] LOOP
        EXECUTE format('ALTER TABLE roles_skills.%I ENABLE ROW LEVEL SECURITY', t);
        EXECUTE format('ALTER TABLE roles_skills.%I FORCE ROW LEVEL SECURITY', t);
        EXECUTE format('CREATE POLICY workspace_isolation ON roles_skills.%I'
                       ' USING (workspace_id = roles_skills.current_workspace())'
                       ' WITH CHECK (workspace_id = roles_skills.current_workspace())', t);
    END LOOP;
END
$$;

GRANT USAGE ON SCHEMA roles_skills TO roles_skills_api;
GRANT EXECUTE ON FUNCTION roles_skills.current_workspace() TO roles_skills_api;
GRANT SELECT, INSERT, UPDATE, DELETE ON roles_skills.personal_roles, roles_skills.role_goal_links, roles_skills.skill_categories, roles_skills.role_project_allocations, roles_skills.personal_role_context_links, roles_skills.personal_role_goal_links, roles_skills.personal_role_project_links, roles_skills.personal_role_task_links, roles_skills.skills, roles_skills.role_path_steps, roles_skills.role_skill_links TO roles_skills_api;
GRANT USAGE ON SEQUENCE roles_skills.personal_roles_id_seq, roles_skills.role_goal_links_id_seq, roles_skills.skill_categories_id_seq, roles_skills.role_project_allocations_id_seq, roles_skills.personal_role_context_links_id_seq, roles_skills.personal_role_goal_links_id_seq, roles_skills.personal_role_project_links_id_seq, roles_skills.personal_role_task_links_id_seq, roles_skills.skills_id_seq, roles_skills.role_path_steps_id_seq, roles_skills.role_skill_links_id_seq TO roles_skills_api;
GRANT SELECT, INSERT ON roles_skills.create_keys TO roles_skills_api;
GRANT SELECT, INSERT ON roles_skills.outbox TO roles_skills_api;
GRANT UPDATE (execution_id, published_at, attempts, next_attempt_at, last_error) ON roles_skills.outbox TO roles_skills_api;

-- The publisher sweeps the outbox of one workspace per token; it reads past RLS for the outbox only.
CREATE POLICY publisher_sweep ON roles_skills.outbox TO roles_skills_publisher USING (true) WITH CHECK (true);
GRANT USAGE ON SCHEMA roles_skills TO roles_skills_publisher;
GRANT SELECT ON roles_skills.outbox TO roles_skills_publisher;
GRANT UPDATE (published_at, attempts, next_attempt_at, last_error) ON roles_skills.outbox TO roles_skills_publisher;
